-- A school database: students and courses, linked by enrollments.
CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT, city TEXT);
CREATE TABLE courses (id INTEGER PRIMARY KEY, title TEXT, teacher TEXT);
CREATE TABLE enrollments (
  student_id INTEGER REFERENCES students(id),
  course_id INTEGER REFERENCES courses(id),
  grade INTEGER
);
INSERT INTO students VALUES (1, 'Ana', 'Austin'), (2, 'Ben', 'Denver'), (3, 'Chen', 'Austin'), (4, 'Dara', 'Boston');
INSERT INTO courses VALUES (10, 'Python', 'Ms. Lee'), (20, 'Web Basics', 'Mr. Diaz'), (30, 'SQL', 'Ms. Lee'), (40, 'Art', 'Mr. Kim');
INSERT INTO enrollments VALUES (1, 10, 95), (1, 30, 88), (2, 10, 72), (2, 20, 81), (3, 30, 90), (3, 20, 77);

SELECT s.name, c.title, c.teacher, e.grade
FROM enrollments e
JOIN students s ON s.id = e.student_id
JOIN courses c ON c.id = e.course_id
ORDER BY s.name, c.title;

SELECT s.name, COUNT(e.course_id) AS courses, ROUND(AVG(e.grade), 1) AS average
FROM students s
LEFT JOIN enrollments e ON e.student_id = s.id
GROUP BY s.id
ORDER BY s.name;

SELECT title FROM courses
WHERE id NOT IN (SELECT course_id FROM enrollments);

